function cheapestCrew(quality: number[], minWage: number[], k: number): number {
  const n = quality.length;
  let best = Infinity;
  for (let c = 0; c < n; c++) {
    const rate = minWage[c] / quality[c];
    const pool: number[] = [];
    for (let i = 0; i < n; i++) {
      if (minWage[i] / quality[i] <= rate) pool.push(quality[i]);
    }
    if (pool.length < k) continue;
    pool.sort((a, b) => a - b);
    let sum = 0;
    for (let i = 0; i < k; i++) sum += pool[i];
    best = Math.min(best, rate * sum);
  }
  return best;
}

