class MaxHeap {
  private a: number[] = [];
  get size(): number { return this.a.length; }
  push(x: number): void {
    const a = this.a;
    a.push(x);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (a[p] >= a[i]) break;
      [a[p], a[i]] = [a[i], a[p]];
      i = p;
    }
  }
  pop(): number {
    const a = this.a, top = a[0], last = a.pop()!;
    if (a.length) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < a.length && a[l] > a[m]) m = l;
        if (r < a.length && a[r] > a[m]) m = r;
        if (m === i) break;
        [a[m], a[i]] = [a[i], a[m]];
        i = m;
      }
    }
    return top;
  }
}

function cheapestCrew(quality: number[], minWage: number[], k: number): number {
  const workers = quality.map((q, i) => [minWage[i] / q, q]).sort((x, y) => x[0] - y[0]);
  const heap = new MaxHeap();
  let sum = 0, best = Infinity;
  for (const [ratio, q] of workers) {
    heap.push(q);
    sum += q;
    if (heap.size > k) sum -= heap.pop();
    if (heap.size === k) best = Math.min(best, ratio * sum);
  }
  return best;
}

